package springboot_based.ams.security;import lombok.AllArgsConstructor;import org.springframework.security.core.userdetails.UserDetails;import org.springframework.security.core.userdetails.UserDetailsService;import org.springframework.security.core.userdetails.UsernameNotFoundException;import org.springframework.stereotype.Service;import springboot_based.ams.entity.User;import springboot_based.ams.repository.UserRepository;@Service@AllArgsConstructorpublic class CustomerUserDetailsService implements UserDetailsService {    private UserRepository userRepository;    @Override    public UserDetails loadUserByUsername(String username) throws UsernameNotFoundException {        User user = userRepository.findByUsername(username)                .orElseThrow(() -> new UsernameNotFoundException("User not found with username: " + username));                return org.springframework.security.core.userdetails.User.builder()                .username(user.getUsername())                .password(user.getPassword())                .roles("USER")                .build();    }}